public interface IRange<TSelf> where TSelf : IRange<TSelf>   // the trait carrier
{
    static abstract TSelf Min { get; }
    static abstract TSelf Max { get; }
}

public static T Clamp<T>(T v) where T : IRange<T>, IComparisonOperators<T, T, bool>
    => v < T.Min ? T.Min : (v > T.Max ? T.Max : v);

// same idea, shipped by the BCL (.NET 7 generic math):
static T Sum<T>(IEnumerable<T> xs) where T : INumber<T>
    => xs.Aggregate(T.Zero, (a, b) => a + b);

sealed class LengthComparer : IComparer<Frame>
{
    public int Compare(Frame? a, Frame? b) => a!.Value.CompareTo(b!.Value);
}
frames.Sort(new LengthComparer());          // the trait is supplied, not inherited

static T Max<T>(T a, T b) where T : IComparable<T> => a.CompareTo(b) > 0 ? a : b;

